import re
from typing import Any, Dict, List, Optional


def run(left: List[Dict[str, Any]], right: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Validate left records have all declared fields
    left_fields = {"request_id", "order_ref", "customer"}
    for record in left:
        for field in left_fields:
            if field not in record:
                raise ValueError(field)

    # Validate right records have all declared fields
    right_fields = {"order_id", "customer", "status"}
    for record in right:
        for field in right_fields:
            if field not in record:
                raise ValueError(field)

    # Normalization: keep only digits 0-9
    def digits_only(s: str) -> str:
        return re.sub(r"[^0-9]", "", s)

    # Build map from normalized order_id to list of right records
    right_norm_map: Dict[str, List[Dict[str, Any]]] = {}
    for r in right:
        k = digits_only(r["order_id"])
        right_norm_map.setdefault(k, []).append(r)

    results: List[Dict[str, Any]] = []
    for l in left:
        k = digits_only(l["order_ref"])

        # No match or empty key
        if not k or k not in right_norm_map:
            results.append({
                "left_id": l["request_id"],
                "right_id": None,
                "status": "order_not_found"
            })
            continue

        matches = right_norm_map[k]

        # Ambiguous match
        if len(matches) > 1:
            results.append({
                "left_id": l["request_id"],
                "right_id": None,
                "status": "manual_review"
            })
            continue

        # Single match
        r = matches[0]
        right_id = r["order_id"]

        # Check: equals_ci on customer
        left_customer = l["customer"]
        right_customer = r["customer"]

        # Wrong type fails the check
        if not isinstance(left_customer, str) or not isinstance(right_customer, str):
            results.append({
                "left_id": l["request_id"],
                "right_id": right_id,
                "status": "customer_mismatch"
            })
            continue

        # Compare after stripping whitespace and ignoring case
        if left_customer.strip().lower() != right_customer.strip().lower():
            results.append({
                "left_id": l["request_id"],
                "right_id": right_id,
                "status": "customer_mismatch"
            })
            continue

        # All checks passed
        results.append({
            "left_id": l["request_id"],
            "right_id": right_id,
            "status": "reply_with_status"
        })

    return results
